<template>
  <v-container class="media-library" fluid>
    <header class="page-header"><div><div class="kicker">MEDIA</div><h1>Your visual memory</h1><p>Keep photos, clips, and audio close to the tasks and moments they belong to.</p></div><v-btn color="primary" size="large" prepend-icon="mdi-cloud-upload-outline" @click="openUpload">Add media</v-btn></header>
    <section class="media-toolbar"><div class="filter-row" role="tablist" aria-label="Filter media"><button v-for="filter in filters" :key="filter.value" :class="{active:selectedFilter===filter.value}" @click="selectedFilter=filter.value"><v-icon :icon="filter.icon" size="18"/>{{ filter.label }}<span>{{ count(filter.value) }}</span></button></div></section>
    <v-alert v-if="store.error" type="error" variant="tonal" closable class="mb-5" @click:close="store.clearError()">{{ store.error }}</v-alert>
    <div v-if="store.loading && !items.length" class="state"><v-progress-circular indeterminate color="primary"/><span>Loading your media…</span></div>
    <section v-else-if="filtered.length" class="media-grid">
      <article v-for="media in filtered" :key="media.id" class="media-tile" tabindex="0" @click="showDetails(media)" @keydown.enter="showDetails(media)">
        <div class="preview">
          <img v-if="media.mediaType==='image'" :src="assetUrl(media.thumbnailUrl || media.fileUrl)" :alt="media.title"/>
          <video v-else-if="media.mediaType==='video'" :src="assetUrl(media.fileUrl)" preload="metadata" muted/>
          <div v-else class="audio-art"><v-icon icon="mdi-waveform" size="48"/></div>
          <span class="type-pill"><v-icon :icon="typeIcon(media.mediaType)" size="14"/>{{ media.mediaType }}</span>
        </div>
        <div class="tile-copy"><h2>{{ media.title }}</h2><p>{{ media.description || `Added ${formatDate(media.createdAt)}` }}</p><div><span>{{ formatFileSize(media.fileSize) }}</span><span v-if="media.tags?.length">{{ media.tags.slice(0,2).join(' · ') }}</span></div></div>
      </article>
    </section>
    <section v-else class="state empty"><span class="empty-icon"><v-icon icon="mdi-image-multiple-outline" size="38"/></span><h2>{{ selectedFilter==='all' ? 'Save your first memory' : `No ${selectedFilter} files yet` }}</h2><p>Upload something useful. Remindly keeps it private unless you choose to share it.</p><v-btn color="primary" prepend-icon="mdi-plus" @click="openUpload">Add media</v-btn></section>

    <v-dialog v-model="uploadDialog" max-width="600"><v-card class="dialog-card" rounded="xl"><v-card-text><div class="kicker">NEW MEDIA</div><h2>Add something to remember</h2><p>Photos, video, and audio up to 100 MB.</p><v-form v-model="formValid" @submit.prevent="upload"><v-file-input v-model="draft.file" label="Choose a file" variant="outlined" accept="image/*,video/*,audio/*" :rules="[required]" prepend-icon="" @update:model-value="detectType"/><v-text-field v-model="draft.title" label="Title" variant="outlined" :rules="[required]"/><v-textarea v-model="draft.description" label="A short note (optional)" variant="outlined" rows="3"/><v-combobox v-model="draft.tags" label="Tags (optional)" variant="outlined" multiple chips closable-chips/><v-switch v-model="draft.isPublic" label="Allow sharing" color="primary" hide-details/><div class="dialog-actions"><v-btn variant="text" @click="uploadDialog=false">Cancel</v-btn><v-btn type="submit" color="primary" :disabled="!formValid" :loading="uploading">Upload media</v-btn></div></v-form></v-card-text></v-card></v-dialog>

    <v-dialog v-model="detailsDialog" max-width="820"><v-card v-if="selected" class="dialog-card detail-card" rounded="xl"><div class="detail-preview"><img v-if="selected.mediaType==='image'" :src="assetUrl(selected.fileUrl)" :alt="selected.title"/><video v-else-if="selected.mediaType==='video'" :src="assetUrl(selected.fileUrl)" controls/><audio v-else :src="assetUrl(selected.fileUrl)" controls/></div><v-card-text><div class="detail-heading"><div><div class="kicker">{{ selected.mediaType.toUpperCase() }}</div><h2>{{ selected.title }}</h2></div><v-btn icon="mdi-close" variant="text" aria-label="Close" @click="detailsDialog=false"/></div><p>{{ selected.description || 'No note added.' }}</p><div class="meta-row"><span>{{ formatDate(selected.createdAt) }}</span><span>{{ formatFileSize(selected.fileSize) }}</span><span>{{ selected.isPublic ? 'Sharing enabled' : 'Private' }}</span></div><div class="detail-actions"><v-btn variant="tonal" prepend-icon="mdi-pencil-outline" @click="startEdit">Edit details</v-btn><v-btn variant="tonal" prepend-icon="mdi-share-variant-outline" :disabled="!selected.isPublic" @click="share">Share</v-btn><v-spacer/><v-btn color="error" variant="text" prepend-icon="mdi-delete-outline" @click="remove">Delete</v-btn></div></v-card-text></v-card></v-dialog>

    <v-dialog v-model="editDialog" max-width="560"><v-card class="dialog-card" rounded="xl"><v-card-text><div class="kicker">EDIT MEDIA</div><h2>Update the details</h2><v-form @submit.prevent="saveEdit"><v-text-field v-model="editDraft.title" label="Title" variant="outlined"/><v-textarea v-model="editDraft.description" label="Note" variant="outlined" rows="3"/><v-combobox v-model="editDraft.tags" label="Tags" variant="outlined" multiple chips/><v-switch v-model="editDraft.isPublic" label="Allow sharing" color="primary"/><div class="dialog-actions"><v-btn variant="text" @click="editDialog=false">Cancel</v-btn><v-btn type="submit" color="primary" :loading="store.loading">Save changes</v-btn></div></v-form></v-card-text></v-card></v-dialog>
  </v-container>
</template>
<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { useMediaGalleryStore } from '@/stores/mediaGalleryStore'
import type { MediaGallery } from '@/types'
const store=useMediaGalleryStore(); const selectedFilter=ref('all'); const uploadDialog=ref(false); const detailsDialog=ref(false); const editDialog=ref(false); const formValid=ref(false); const uploading=ref(false); const selected=ref<MediaGallery|null>(null)
const filters=[{value:'all',label:'Everything',icon:'mdi-view-grid-outline'},{value:'image',label:'Photos',icon:'mdi-image-outline'},{value:'video',label:'Videos',icon:'mdi-video-outline'},{value:'audio',label:'Audio',icon:'mdi-waveform'}]
const draft=reactive<{title:string;description:string;file:File|null;mediaType:'image'|'video'|'audio';tags:string[];isPublic:boolean}>({title:'',description:'',file:null,mediaType:'image',tags:[],isPublic:false}); const editDraft=reactive({title:'',description:'',tags:[] as string[],isPublic:false})
const items=computed(()=>store.mediaItems); const filtered=computed(()=>selectedFilter.value==='all'?items.value:items.value.filter(i=>i.mediaType===selectedFilter.value)); const count=(type:string)=>type==='all'?items.value.length:items.value.filter(i=>i.mediaType===type).length
const required=(v:any)=>Boolean(Array.isArray(v)?v.length:v)||'Required'; const typeIcon=(type:string)=>({image:'mdi-image-outline',video:'mdi-video-outline',audio:'mdi-waveform'}[type]||'mdi-file-outline')
const assetUrl=(url?:string)=>url||''; const formatDate=(d:Date|string)=>new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}); const formatFileSize=(bytes=0)=>bytes<1024?`${bytes} B`:bytes<1048576?`${(bytes/1024).toFixed(1)} KB`:`${(bytes/1048576).toFixed(1)} MB`
const reset=()=>Object.assign(draft,{title:'',description:'',file:null,mediaType:'image',tags:[],isPublic:false}); const openUpload=()=>{reset();uploadDialog.value=true}; const detectType=(files:File|File[]|null)=>{const file=Array.isArray(files)?files[0]:files;if(!file)return;draft.file=file;draft.mediaType=file.type.startsWith('video')?'video':file.type.startsWith('audio')?'audio':'image';if(!draft.title)draft.title=file.name.replace(/\.[^.]+$/,'')}
const upload=async()=>{if(!draft.file)return;uploading.value=true;const result=await store.addMediaItem({...draft,file:draft.file});uploading.value=false;if(result.success){uploadDialog.value=false;reset()}}
const showDetails=(item:MediaGallery)=>{selected.value=item;detailsDialog.value=true}; const startEdit=()=>{if(!selected.value)return;Object.assign(editDraft,{title:selected.value.title,description:selected.value.description||'',tags:[...(selected.value.tags||[])],isPublic:selected.value.isPublic});editDialog.value=true}
const saveEdit=async()=>{if(!selected.value)return;const result=await store.updateMediaItem(selected.value.id,editDraft);if(result.success){selected.value=result.mediaItem!;editDialog.value=false}}
const share=async()=>{if(!selected.value)return;const result=await store.shareMediaItem(selected.value.id);if(result.success&&result.shareUrl){if(navigator.share)await navigator.share({title:selected.value.title,url:result.shareUrl});else await navigator.clipboard.writeText(result.shareUrl)}}
const remove=async()=>{if(!selected.value||!confirm(`Delete “${selected.value.title}”?`))return;const result=await store.deleteMediaItem(selected.value.id);if(result.success){detailsDialog.value=false;selected.value=null}}
onMounted(()=>store.loadMediaItems())
</script>
<style scoped>
.media-library{max-width:1180px;padding:42px 28px 80px}.page-header{display:flex;align-items:end;justify-content:space-between;gap:28px;margin-bottom:28px}.page-header h1{font-size:clamp(2.4rem,5vw,4.5rem);line-height:.96;letter-spacing:-.055em;color:#173d3a;margin:0 0 14px}.page-header p{max-width:620px;color:#687572;margin:0}.kicker{font:700 11px ui-monospace,monospace;letter-spacing:.14em;color:#245b55;margin-bottom:10px}.media-toolbar{border-block:1px solid #dce3df;padding:14px 0;margin-bottom:24px;overflow:auto}.filter-row{display:flex;gap:8px}.filter-row button{height:42px;white-space:nowrap;border:1px solid #dce3df;border-radius:13px;background:#fff;padding:0 14px;display:flex;align-items:center;gap:7px;color:#52625f;font-weight:650}.filter-row button span{font-size:.68rem;background:#eef3f1;border-radius:20px;padding:2px 7px}.filter-row button.active{background:#173d3a;color:#fff;border-color:#173d3a}.media-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px}.media-tile{background:#fff;border:1px solid #dce3df;border-radius:20px;overflow:hidden;cursor:pointer;outline:none;transition:.2s}.media-tile:hover,.media-tile:focus-visible{border-color:#7fa8a0;box-shadow:0 12px 30px rgba(23,61,58,.09)}.preview{height:190px;background:#dceee6;position:relative;overflow:hidden}.preview img,.preview video{width:100%;height:100%;object-fit:cover}.audio-art{width:100%;height:100%;display:grid;place-items:center;color:#245b55;background:repeating-linear-gradient(90deg,#dceee6 0 8px,#e8f3ee 8px 16px)}.type-pill{position:absolute;left:12px;top:12px;background:rgba(23,61,58,.88);color:#fff;border-radius:30px;padding:5px 9px;display:flex;align-items:center;gap:5px;font-size:.68rem;text-transform:capitalize}.tile-copy{padding:16px}.tile-copy h2{color:#173d3a;font-size:1.05rem;margin:0 0 5px}.tile-copy p{color:#687572;font-size:.8rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin:0 0 15px}.tile-copy>div{border-top:1px solid #edf1ef;padding-top:12px;display:flex;justify-content:space-between;color:#7b8784;font-size:.68rem}.state{min-height:340px;display:grid;place-content:center;justify-items:center;text-align:center;gap:14px}.state p{max-width:430px;color:#687572}.empty-icon{width:72px;height:72px;border-radius:22px;background:#dceee6;color:#245b55;display:grid;place-items:center}.dialog-card .v-card-text{padding:30px}.dialog-card h2{color:#173d3a;font-size:2rem;margin:0 0 8px}.dialog-card> .v-card-text>p{color:#687572;margin-bottom:22px}.dialog-actions,.detail-actions,.detail-heading,.meta-row{display:flex;align-items:center}.dialog-actions{justify-content:flex-end;gap:8px}.detail-preview{min-height:240px;max-height:460px;background:#102f2c;display:grid;place-items:center}.detail-preview img,.detail-preview video{width:100%;max-height:460px;object-fit:contain}.detail-preview audio{width:min(90%,560px)}.detail-heading{justify-content:space-between}.meta-row{gap:8px;flex-wrap:wrap;margin:20px 0}.meta-row span{background:#eef3f1;color:#52625f;padding:6px 9px;border-radius:10px;font-size:.72rem}.detail-actions{gap:8px}@media(max-width:700px){.media-library{padding:26px 14px 78px}.page-header{align-items:flex-start;flex-direction:column}.page-header .v-btn{width:100%}.media-grid{grid-template-columns:1fr 1fr}.preview{height:145px}.dialog-actions,.detail-actions{flex-direction:column-reverse;align-items:stretch}.detail-actions .v-spacer{display:none}}@media(max-width:440px){.media-grid{grid-template-columns:1fr}}
</style>
